contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint setMin, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(collectAmount <= depositAmount);

        c.SetMinSum(setMin); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint beforeUserBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterUserBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        assert(!reverted || (afterUserBal + collectAmount == beforeUserBal && afterContractBal + collectAmount == beforeContractBal));
    }

    receive() external payable {}
}

