pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmount, uint256 setMin, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(collectAmount <= depositAmount);
        try c.SetMinSum(setMin) {} catch { return; }
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 beforeUserBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeUserBal = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUserBal;
        try c.balances(address(this)) returns (uint256 __r) { afterUserBal = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(!reverted || (afterUserBal + collectAmount == beforeUserBal && afterContractBal + collectAmount == beforeContractBal));
    }

    function testFuzz_run(uint256 depositAmount, uint256 setMin, uint256 collectAmount) public {
        _run(depositAmount, setMin, collectAmount);
    }

    receive() external payable {}
}
